import{_ as t,o as e,c as i,a2 as l}from"./chunks/framework.CAKCj7G0.js";const h=JSON.parse('{"title":"欢迎来到我的花园","description":"","frontmatter":{"layout":"home","hero":{"name":"欢迎来到我的花园","text":"","tagline":"大道五十，天衍四九，人遁其一。世间万事，无人力不可为，无人力不可解。","image":{"src":"/assets/logo.svg","alt":"Logo"},"actions":[{"theme":"brand","text":"开始阅读","link":"/README"},{"theme":"alt","text":"GitHub","link":"https://github.com/canaan-wang/canaan-wang.github.io"}]},"features":[{"title":"🌿 Go 语言","details":"从基础语法到并发模型，深入 Go 语言核心特性与框架实践。","link":"/Go/Golang/Go语言概览"},{"title":"☕ Java 生态","details":"JVM、Spring 全家桶、并发编程与集合框架的系统学习。","link":"/Java/Java/Java语言概览"},{"title":"🗄️ 数据库","details":"MySQL、Redis、Elasticsearch 的原理与实战笔记。","link":"/数据库/Redis/Redis"},{"title":"📐 计算机理论","details":"数据结构、分布式系统、网络协议、设计原则等底层知识。","link":"/理论/数据结构/skiplist"},{"title":"🔧 中间件","details":"消息队列、缓存、配置中心、Docker 等基础设施技术。","link":"/中间件/消息队列/kafka/Kafka"},{"title":"🍳 生活随笔","details":"工作记录、菜谱分享、生活感悟，记录平凡中的美好。","link":"/生活/"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),n={name:"index.md"};function o(s,a,p,r,d,c){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="欢迎来到我的花园" tabindex="-1">欢迎来到我的花园 <a class="header-anchor" href="#欢迎来到我的花园" aria-label="Permalink to &quot;欢迎来到我的花园&quot;">​</a></h1><blockquote><p>拥有一颗平静的心，才能看到诗和远方。</p></blockquote><h2 id="关于我-q-a" tabindex="-1">关于我（Q&amp;A） <a class="header-anchor" href="#关于我-q-a" aria-label="Permalink to &quot;关于我（Q&amp;A）&quot;">​</a></h2><ul><li><p>Q：有些什么爱好？</p></li><li><p>A：平时有空喜欢去一些没有到达过的新奇地点，喜欢自然，心怡山水。资深小说党，喜欢看大世界观、每个族群为自身发展而努力；lv2 小说作家，为爱发电。</p></li><li><p>Q：家庭如何？</p></li><li><p>A：我有与我相爱的妻子、可爱的孩子。哈哈哈哈，如果可以的话，现在极其想和你分享我家的小宝。</p></li><li><p>Q：对事业的看法？</p></li><li><p>A：这可能是一个比较严肃的话题，不过通过上边的介绍你大致可以看出我是一个不怎么严肃的人。我觉得事业是生活中人所实现自身价值的直接途径，失去自身的事业，人会变得极其空虚。</p></li><li><p>Q：对工作的看法？</p></li><li><p>A：借用《工作的意义》这本书的概念，工作本身是对彼此的服侍，所有人共同组成一个和谐的社会。工作和事业本质是不同的概念，工作是我们完成自身事业的直接途径。当然，并不是所有的工作都是为自身事业的发展，我们在社会中是需要生存的。所有人都希望有更好的生活条件。但不是说只有获得更多金币的工作才是好工作。比方说，家庭主妇（我个人还是不太建议家庭主妇）对整个家庭起到了非常积极的支撑作用。但相应的，女性在社会、职场上也会失去很多（我并非女权者，仅是站在客观角度上看待这些事情）。</p></li><li><p>Q：对人性的看法？</p></li><li><p>A：我认为人性是极其复杂的矛盾体，在抉择中有得有失。但我仍然相信大多数人是善良的，只不过并非是因为人性，而是因为人类社会的法律、道德体系。至于人性，不可解，不可查。</p></li></ul>',4)])])}const k=t(n,[["render",o]]);export{h as __pageData,k as default};
